+++ src/suma.test.mjs	
@@ -0,0 +1,64 @@
+import { describe, it } from 'node:test';
+import assert from 'node:assert/strict';
+
+// Helper compartido: import dinámico con caché de módulo
+async function getSuma() {
+  const { suma } = await import('./suma.mjs');
+  return suma;
+}
+
+// CA-1: Suma de dos enteros positivos
+describe('CA-1: Suma de dos enteros positivos', () => {
+  it('devuelve 3 cuando a=1 y b=2', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(1, 2), 3);
+  });
+
+  it('devuelve 10 cuando a=4 y b=6', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(4, 6), 10);
+  });
+
+  it('devuelve 0 cuando a=0 y b=0', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(0, 0), 0);
+  });
+});
+
+// CA-2: Suma con signo mixto
+// Dado un número entero positivo a y uno negativo b,
+// cuando se invoca suma(a, b),
+// entonces devuelve a + b como resultado correcto.
+describe('CA-2: Suma con signo mixto', () => {
+  it('devuelve -1 cuando a=2 y b=-3', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(2, -3), -1);
+  });
+
+  it('devuelve 0 cuando a=5 y b=-5', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(5, -5), 0);
+  });
+
+  it('devuelve 8 cuando a=10 y b=-2', async () => {
+    const suma = await getSuma();
+    assert.strictEqual(suma(10, -2), 8);
+  });
+});
+
+// CA-3: Exportación como módulo ES
+// Dado que src/suma.mjs es un módulo ES,
+// cuando se importa mediante import { suma } from './suma.mjs',
+// entonces suma está disponible como exportación nombrada.
+describe('CA-3: Exportación como módulo ES', () => {
+  it('suma es una exportación nombrada del módulo', async () => {
+    const mod = await import('./suma.mjs');
+    assert.ok('suma' in mod);
+    assert.strictEqual(typeof mod.suma, 'function');
+  });
+
+  it('no exporta default que interfiera', async () => {
+    const mod = await import('./suma.mjs');
+    assert.strictEqual(mod.default, undefined);
+  });
+});
